const norm = $('A - Normalize Mission Data').first().json;
const pg   = $input.first().json;
return [{ json: { ...norm, internal_mission_id: pg.id, current_status: pg.status } }];

const ctx  = $('A - Merge Mission ID').first().json;
const cand = $input.first().json;
return [{ json: { ...ctx, candidate_db_id: cand.id, phone: cand.phone, email: cand.email, name: cand.name } }];

const d = $input.first().json;
const dt = new Date(d.mission_date);
const dateStr = dt.toLocaleDateString('fr-FR',{weekday:'long',year:'numeric',month:'long',day:'numeric'});
const sms = `Bonjour ${d.name||d.candidate_name}, vous êtes proposé(e) pour une mission le ${dateStr} à ${d.start_time||'09:00'} (${d.location}). Répondez OUI pour confirmer ou NON pour décliner. Ref: ${d.ats_mission_id}`;
const r1=new Date(d.mission_date+'T'+(d.start_time||'09:00')+':00');
r1.setDate(r1.getDate()-2);r1.setHours(10,0,0,0);
const r2=new Date(d.mission_date+'T'+(d.start_time||'09:00')+':00');
r2.setDate(r2.getDate()-1);r2.setHours(16,0,0,0);
const r3=new Date(d.mission_date+'T'+(d.start_time||'09:00')+':00');
r3.setHours(r3.getHours()-2);
return [{json:{...d,sms_body:sms,reminder_1_scheduled:r1.toISOString(),reminder_2_scheduled:r2.toISOString(),reminder_3_scheduled:r3.toISOString()}}];

const text=($input.first().json.message_text||'').toUpperCase().trim();
const d=$input.first().json;
const YES=['OUI','YES','OK','CONFIRME','CONFIRMÉ','D ACCORD','DACCORD','PRESENT','PRÉSENT','1'];
const NO=['NON','NO','REFUSE','REFUSÉ','IMPOSSIBLE','PAS DISPONIBLE','INDISPONIBLE','0','ANNULE','ANNULÉ'];
const STOP=['STOP','DESINSCRIPTION','DÉSABONNER','UNSUBSCRIBE','CANCEL'];
let cl='UNCLEAR';
if(STOP.some(p=>text.includes(p)))cl='STOP';
else if(YES.some(p=>text===p||text.startsWith(p+' ')||text.startsWith(p+',')))cl='YES';
else if(NO.some(p=>text===p||text.startsWith(p+' ')||text.startsWith(p+',')))cl='NO';
return [{json:{...d,inbound_text:$('B - Normalize Inbound').first().json.message_text,classification:cl}}];

const now=new Date();
const results=[];
for(const item of $input.all()){
  const d=item.json;
  const mdt=new Date(`${d.mission_date}T${d.start_time||'09:00'}:00`);
  const diffH=(mdt-now)/(1000*60*60);
  let action=null;
  if(diffH<=0&&diffH>-1&&!d.reminder_3_sent_at) action='HIGH_RISK_NO_RESPONSE';
  else if(diffH<=2&&diffH>0&&!d.reminder_3_sent_at) action='REMINDER_3_H2';
  else if(!d.reminder_2_sent_at&&d.reminder_2_scheduled_at){
    const diff=(now-new Date(d.reminder_2_scheduled_at))/60000;
    if(diff>=0&&diff<45) action='REMINDER_2_J1';
  } else if(!d.reminder_1_sent_at&&d.reminder_1_scheduled_at){
    const diff=(now-new Date(d.reminder_1_scheduled_at))/60000;
    if(diff>=0&&diff<45) action='REMINDER_1_J2';
  }
  if(action) results.push({json:{...d,action}});
}
return results;

const candidates=$input.all().map(i=>i.json);
const m=$('D - Normalize Backup Request').first().json;
let txt=`*Shortlist Backup — Mission ${m.ats_mission_id}*\n📅 ${m.mission_date} | 📍 ${m.location}\n🔧 ${m.skill_required} | Raison: ${m.reason}\n\n`;
candidates.forEach((c,i)=>{
  const sc=Math.round(c.ranking_score||0);
  txt+=`${i+1}. *${c.name}* (Score:${sc}/100) 📞 ${c.phone} | Absence:${Math.round((c.absence_rate||0)*100)}% | Retard:${Math.round((c.late_rate||0)*100)}%\n`;
});
return [{json:{shortlist:candidates,shortlist_text:txt,top_candidate:candidates[0]||null,mission:m,count:candidates.length}}];

const d=$input.first().json;
const trigger=$('E - Normalize Risk Input').first().json.trigger;
const rtScore=Math.max(0,Math.min(100,d.avg_response_time_minutes!=null?Math.max(0,100-(d.avg_response_time_minutes/60)*20):50));
const absScore=Math.max(0,100-((d.absence_rate||0)*100)*2);
const lateScore=Math.max(0,100-((d.late_rate||0)*100)*1.5);
const noReplyScore=Math.max(0,100-(d.no_reply_count||0)*15);
const last30dScore=Math.min(100,(d.recent_mission_count||0)*10);
const remindersNeeded=[d.reminder_1_sent_at,d.reminder_2_sent_at,d.reminder_3_sent_at].filter(Boolean).length;
const clarityScore=Math.max(0,100-remindersNeeded*25);
return [{json:{...d,features:{response_time_score:Math.round(rtScore),absence_score:Math.round(absScore),late_score:Math.round(lateScore),no_reply_score:Math.round(noReplyScore),last30d_score:Math.round(last30dScore),clarity_score:Math.round(clarityScore),reminders_needed:remindersNeeded,current_status:d.current_status,trigger}}}];

