const ai=$input.first().json;
const orig=$('E - Compute Features').first().json;
let parsed;
try{parsed=JSON.parse(ai.choices?.[0]?.message?.content||'{}');}catch(e){parsed={risk_score:75,risk_level:'HIGH',main_risk_factors:['Parse error'],recommended_actions:['Manual review'],confidence:0};}
return [{json:{...orig,risk_score:parsed.risk_score||0,risk_level:parsed.risk_level||'MEDIUM',main_risk_factors:parsed.main_risk_factors||[],recommended_actions:parsed.recommended_actions||[],ai_confidence:parsed.confidence||0,is_high_risk:(parsed.risk_score||0)>=70}}];

const c=$input.first().json;
const t=(c.total_missions_count||0)+1,p=(c.present_count||0)+1,a=c.absent_count||0,l=c.late_count||0;
const ar=t>0?a/t:0,lr=t>0?l/t:0;
const rs=Math.round(Math.max(0,Math.min(100,100-(ar*100*2)-(lr*100*1)-((c.no_reply_count||0)*3))));
return [{json:{...c,outcome:'PRESENT',new_total:t,new_present:p,new_absent:a,new_late:l,new_absence_rate:ar,new_late_rate:lr,new_reliability_score:rs}}];

